// Checks whether the slice `a` contains the element `x`.
fn is_in_array(a: &[i32], x: i32) -> bool {
    for &item in a {
        if item == x {
            return true;
        }
    }
    false
}

// Checks whether the vector `v` contains the element `x`.
fn contains(v: &Vec<i32>, x: i32) -> bool {
    // Reuse `is_in_array` on the slice view of `v`.
    is_in_array(v.as_slice(), x)
}

// Returns a Vec of all distinct elements that appear in `a` but not in `b`.
fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    for &x in a {
        // include x if it's not in b and not already in result
        if !is_in_array(b, x) && !contains(&result, x) {
            result.push(x);
        }
    }
    result
}

// Example usage and simple test
fn main() {
    let a = [1, 2, 2, 3, 4, 5];
    let b = [2, 4, 6];
    let c = remove_elements(&a, &b);
    // c should be [1, 3, 5] in some order (here it will preserve the
    // first-seen order from `a`).
    assert_eq!(c, vec![1, 3, 5]);
    println!("Result: {:?}", c);
}